        body: `▼ゼロから：電気を「水の流れ」で考えると一気に分かる
・水道管を思いうかべる。ポンプが水を押し出す力が「電圧V」、流れる水の量が「電流I」、管の細さや詰まりが「抵抗R」
・押す力が強いほど水はたくさん流れる → 電圧が高いほど電流は大きい
・管が細いほど水は流れにくい → 抵抗が大きいほど電流は小さい
・この当たり前の関係を式にしただけのものが「オームの法則」
・第二種電気工事士の計算問題は、ほぼすべてこの一本の式から枝分かれしている
⚠ 例えの限界：水は管が切れても出ていくが、電気は輪（回路）がつながっていないと1アンペアも流れない

━━━━━━━━━━━━━━━━━━━━━━
🔑 オームの法則の3つの形
━━━━━━━━━━━━━━━━━━━━━━
○基本形：V＝IR（電圧＝電流×抵抗）★
○電流を求める形：I＝V÷R★
○抵抗を求める形：R＝V÷I★
・単位：V［ボルト V］、I［アンペア A］、R［オーム Ω］
・3つの文字のうち2つが分かれば、残りの1つは必ず求まる
・電圧のことを「電位差」ともいう。2点の高さの差だと思えばよい
・抵抗の逆数はコンダクタンスG＝1÷R［ジーメンス S］。並列計算のとき役に立つ

━━━━━━━━━━━━━━━━━━━━━━
🔑 単位の接頭語をそろえてから計算する
━━━━━━━━━━━━━━━━━━━━━━
・k（キロ）＝1000倍、M（メガ）＝100万倍
・m（ミリ）＝1000分の1、μ（マイクロ）＝100万分の1
・計算前にすべてV・A・Ωの基本単位へ直すのが失点しない鉄則★
・例：2kΩ＝2000Ω、500mA＝0.5A、100μF＝0.0001F

【図解】オームの法則の基本3パターン（数値で確認）
　求めるもの｜式｜代入と答え
　電圧V｜V＝IR｜5A×20Ω＝100 V★
　電流I｜I＝V÷R｜100V÷20Ω＝5 A★
　抵抗R｜R＝V÷I｜100V÷5A＝20 Ω★
　⇒ 同じ回路を3通りに聞かれるだけ。式は1本しかない
　⚠ 単位換算を忘れて2kΩを2として計算するミスが最頻出

━━━━━━━━━━━━━━━━━━━━━━
🔑 例題1：基本のオームの法則
━━━━━━━━━━━━━━━━━━━━━━
【例題】100Vの電源に25Ωの抵抗をつないだ。流れる電流は何アンペアか。
・式：I＝V÷R
・代入：I＝100÷25
・答え：I＝4 A★
【例題】この抵抗の両端の電圧を測ると100Vだった。抵抗に流れる電流を2Aにするには抵抗を何Ωにすればよいか。
・式：R＝V÷I
・代入：R＝100÷2
・答え：R＝50 Ω★

━━━━━━━━━━━━━━━━━━━━━━
🔑 例題2：ミリアンペアとキロオーム
━━━━━━━━━━━━━━━━━━━━━━
【例題】24Vの電源に4.8kΩの抵抗をつないだときの電流は何ミリアンペアか。
・まず単位をそろえる：4.8kΩ＝4800Ω
・式：I＝V÷R
・代入：I＝24÷4800＝0.005 A
・答え：0.005A＝5 mA★
→ 「V÷kΩ＝mA」と覚えておくと換算せずに一発で出せる（24÷4.8＝5mA）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 電気回路の基本ルール
━━━━━━━━━━━━━━━━━━━━━━
・回路が1周つながっている状態を「閉回路」、切れている状態を「開路（断線）」という
・開路では抵抗が無限大とみなせるので電流は0A
・電線どうしが直接つながってしまうことを「短絡（ショート）」といい、抵抗がほぼ0Ωなので極めて大きな電流が流れる★
・短絡電流を遮断するのが配線用遮断器やヒューズの役目
・電流の向きは「プラスからマイナスへ」と決められている（電子の移動はその逆向き）★

【図解】回路の状態と電流の大きさ
　状態｜回路の抵抗｜流れる電流
　正常な負荷｜数Ω～数百Ω｜適正な値
　断線（開路）｜無限大｜0 A★
　短絡（ショート）｜ほぼ0Ω｜きわめて大★
　⇒ 断線と短絡は「抵抗が両極端になった状態」と理解する
　⚠ 短絡は電流0だと勘違いしやすい。0になるのは断線のほう

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
×電圧を2倍にしても電流は変わらない → ○抵抗が一定なら電流も2倍になる
×抵抗を2倍にすると電流も2倍 → ○電流は半分になる（反比例）★
×kΩとmAが混ざった問題でそのまま割り算する → ○必ず単位をそろえるか、V÷kΩ＝mAの関係を使う
・実際の出題では「回路図中の抵抗に流れる電流」「抵抗値」を問う形が定番
・数値は100V・200Vなど実用的な値が使われ、答えは整数になるよう作られている★

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★V＝IR、I＝V÷R、R＝V÷I（この3つは同じ式）
★電流は電圧に比例し、抵抗に反比例する
★計算前に必ずV・A・Ωへ単位をそろえる
★V÷kΩ＝mA、V÷Ω＝A
★断線は電流0A、短絡は電流きわめて大
★電流の向きはプラス→マイナス、電子の移動はその逆`,
