・直列では電流が共通なので、発熱P＝I²Rは抵抗に正比例する★
・つまり抵抗の大きい電熱線ほど熱くなる
【例題】100Vに20Ωと30Ωの電熱線を直列接続した。それぞれの消費電力は。
