・電線も同じで、形が同じでも材料が違えば電気の通りにくさが変わる★
・この「材料そのものの通しにくさ」を数値化したものが抵抗率ρ（ロー）
・逆に「材料そのものの通しやすさ」が導電率σ（シグマ）で、ρの逆数★
・銅は抵抗率が小さいので電線に、ニクロムは大きいので発熱体に使われる
